def assert_encloses(result, geometry):
    """The result must enclose the input (a buffer absorbs rounding on contact)."""
    if geometry.is_empty:
        assert result.wkt == "POLYGON EMPTY"
        return
    hull = shapely.force_2d(shapely.convex_hull(geometry))
